def test_UniprotInfo_length():
    lengths = {'O60281': 2723, 'Q15149': 4684, 'Q03661': 1658, 'P42945': 1769}
    for uniid in lengths.keys():
        res = UniprotInfo(uniid).get_overall_length()
        assert res == lengths[uniid]


